document.addEventListener("DOMContentLoaded", function () {
    const triggers = document.querySelectorAll(
        ".has-megamenu > .mega-menu-trigger"
    );

    triggers.forEach(function (trigger) {
        const parentItem = trigger.closest(".has-megamenu");

        trigger.addEventListener("click", function () {
            const isOpen = parentItem.classList.toggle("is-open");
            trigger.setAttribute("aria-expanded", isOpen ? "true" : "false");
        });
    });

    document.addEventListener("click", function (e) {
        triggers.forEach(function (trigger) {
            const parentItem = trigger.closest(".has-megamenu");
            if (!parentItem.contains(e.target)) {
                parentItem.classList.remove("is-open");
                trigger.setAttribute("aria-expanded", "false");
            }
        });
    });

    document.addEventListener("keydown", function (e) {
        if (e.key === "Escape") {
            triggers.forEach(function (trigger) {
                trigger.closest(".has-megamenu").classList.remove("is-open");
                trigger.setAttribute("aria-expanded", "false");
            });
        }
    });
});
